const N:usize=64;const MAX_ARCS:usize=4096;
unsafe fn put(out:*mut u8,slot:usize,v:i64){let bits=v as u64;for b in 0..8{*out.add(slot*8+b)=(bits>>(8*b)) as u8}}
#[no_mangle] pub unsafe extern "C" fn bidirectional_bfs(input:*const i64,len:usize,out:*mut u8,cap:usize)->i64{if input.is_null()||len<4{return -1}let a=std::slice::from_raw_parts(input,len);let(nv,av,sv,tv)=(a[0],a[1],a[2],a[3]);if nv<1||nv>N as i64||av<0||av>MAX_ARCS as i64||sv<0||sv>=nv||tv<0||tv>=nv||len!=4+2*av as usize{return -1}let n=nv as usize;let m=av as usize;let mut edge=[[false;N];N];let mut adj=[[0usize;N];N];let mut deg=[0usize;N];for i in 0..m{let(u,v)=(a[4+2*i],a[5+2*i]);if u<0||u>=nv||v<0||v>=nv{return -1}let(u,v)=(u as usize,v as usize);if !edge[u][v]{edge[u][v]=true;adj[u][deg[u]]=v;deg[u]+=1}}for u in 0..n{for v in 0..n{if edge[u][v]!=edge[v][u]{return -1}}}let(start,target)=(sv as usize,tv as usize);let mut path=[0usize;N];let mut pc=0;if start==target{path[pc]=start;pc+=1}else{let mut seen=[[false;N];2];let mut parent=[[-1i32;N];2];let mut q=[[0usize;N];2];let mut head=[0usize;2];let mut tail=[0usize;2];seen[0][start]=true;seen[1][target]=true;q[0][0]=start;q[1][0]=target;tail=[1,1];let mut meet=None;while head[0]<tail[0]&&head[1]<tail[1]&&meet.is_none(){let end=tail[0];while head[0]<end{let u=q[0][head[0]];head[0]+=1;for j in 0..deg[u]{let v=adj[u][j];if seen[0][v]{continue}seen[0][v]=true;parent[0][v]=u as i32;q[0][tail[0]]=v;tail[0]+=1}}for v in 0..n{if seen[0][v]&&seen[1][v]{meet=Some(v);break}}if meet.is_some(){break}let end=tail[1];while head[1]<end{let u=q[1][head[1]];head[1]+=1;for j in 0..deg[u]{let v=adj[u][j];if seen[1][v]{continue}seen[1][v]=true;parent[1][v]=u as i32;q[1][tail[1]]=v;tail[1]+=1}}for v in 0..n{if seen[0][v]&&seen[1][v]{meet=Some(v);break}}}if let Some(v)=meet{let mut rev=[0usize;N];let mut k=0;let mut cur=v as i32;while cur!=-1{rev[k]=cur as usize;k+=1;cur=parent[0][cur as usize]}while k>0{k-=1;path[pc]=rev[k];pc+=1}let mut cur=parent[1][v];while cur!=-1{path[pc]=cur as usize;pc+=1;cur=parent[1][cur as usize]}}}let bytes=(1+pc)*8;if out.is_null()||cap<bytes{return -2}put(out,0,pc as i64);for i in 0..pc{put(out,1+i,path[i] as i64)}bytes as i64}
